for (size_t i = start; i < end; i++) {
    Particle* p = &particles[i];

    // Calculate acceleration and update velocity
    glm::vec3 acceleration = p->force / p->density + glm::vec3(0, g, 0);
    p->velocity += acceleration * deltaTime;

    // Update position
    p->position += p->velocity * deltaTime;

    // Apply boundary conditions (box collision)
    if (p->position.y < h) {
        p->position.y = -p->position.y + 2 * h + BOX_COLLISION_OFFSET;
        p->velocity.y = -p->velocity.y * elasticity;
    }

    if (p->position.x < h - boxWidth) {
        p->position.x = -p->position.x + 2 * (h - boxWidth) + BOX_COLLISION_OFFSET;
        p->velocity.x = -p->velocity.x * elasticity;
    }

    if (p->position.x > -h + boxWidth) {
        p->position.x = -p->position.x + 2 * (-h + boxWidth) - BOX_COLLISION_OFFSET;
        p->velocity.x = -p->velocity.x * elasticity;
    }

    if (p->position.z < h - boxWidth) {
        p->position.z = -p->position.z + 2 * (h - boxWidth) + BOX_COLLISION_OFFSET;
        p->velocity.z = -p->velocity.z * elasticity;
    }

    if (p->position.z > -h + boxWidth) {
        p->position.z = -p->position.z + 2 * (-h + boxWidth) - BOX_COLLISION_OFFSET;
        p->velocity.z = -p->velocity.z * elasticity;
    }

    // Update transform matrix
    particleTransforms[i] = glm::translate(p->position) * glm::scale(glm::vec3(h / 2.f));
}

